class RPGCharacter:
    MAX_HP = 100
    MAX_LEVEL = 100
    EXP_PER_LEVEL = 100
    HEAL_AMOUNT = 10
    LEVEL_UP_HP_GAIN = 20
    LEVEL_UP_ATTACK_GAIN = 5
    LEVEL_UP_DEFENSE_GAIN = 5
    MIN_DAMAGE = 1

    def __init__(self, name, hp, attack_power, defense, level=1):
        self._name = name
        self._hp = hp
        self._attack_power = attack_power
        self._defense = defense
        self._level = level
        self._exp = 0

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    @property
    def hp(self):
        return self._hp

    @hp.setter
    def hp(self, value):
        self._hp = value

    @property
    def attack_power(self):
        return self._attack_power

    @attack_power.setter
    def attack_power(self, value):
        self._attack_power = value

    @property
    def defense(self):
        return self._defense

    @defense.setter
    def defense(self, value):
        self._defense = value

    @property
    def level(self):
        return self._level

    @level.setter
    def level(self, value):
        self._level = value

    @property
    def exp(self):
        return self._exp

    @exp.setter
    def exp(self, value):
        self._exp = value

    def attack(self, other_character):
        damage = self.calculate_damage(other_character)
        other_character.hp -= damage

    def calculate_damage(self, other_character):
        return max(self.attack_power - other_character.defense, self.MIN_DAMAGE)

    def heal(self):
        self.hp = min(self.hp + self.HEAL_AMOUNT, self.MAX_HP)
        return self.hp

    def gain_exp(self, amount):
        while amount > 0:
            exp_to_level = self.level * self.EXP_PER_LEVEL - self.exp
            if amount >= exp_to_level:
                amount -= exp_to_level
                self.level_up()
            else:
                self.exp += amount
                break

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.hp = min(self.hp + self.LEVEL_UP_HP_GAIN, self.MAX_HP)
            self.attack_power += self.LEVEL_UP_ATTACK_GAIN
            self.defense += self.LEVEL_UP_DEFENSE_GAIN
        return self.level, self.hp, self.attack_power, self.defense

    def is_alive(self):
        return self.hp > 0
